type:
∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {H : Type u_2} [inst_2 : TopologicalSpace H]
  {I : ModelWithCorners ℝ E H} {M : Type u_3} [inst_3 : MetricSpace M] [inst_4 : ChartedSpace H M]
  [inst_5 : IsManifold I (↑⊤) M] [inst_6 : CompactSpace M] [inst_7 : GromovCompactness.ClosedTameTarget I M]
  {u_seq : ℕ → ↑GromovCompactness.CP1 → M} {B : ℝ} {thresh : GromovCompactness.Analysis.TargetThresholds I M}
  (self : GromovCompactness.Compactness.ConcentrationData I u_seq B thresh) (p : ↑GromovCompactness.CP1),
  p ∈ self.S ↔ ENNReal.ofReal thresh.ε_reg ≤ self.μ {p}

∀ {T : GromovCompactness.SphereTree} {toEquiv : Equiv.Perm T.V}
  {map_adj' : ∀ (u v : T.V), T.adj.Adj (toEquiv u) (toEquiv v) ↔ T.adj.Adj u v} {toEquiv_1 : Equiv.Perm T.V}
  {map_adj'_1 : ∀ (u v : T.V), T.adj.Adj (toEquiv_1 u) (toEquiv_1 v) ↔ T.adj.Adj u v},
  { toEquiv := toEquiv, map_adj' := map_adj' } = { toEquiv := toEquiv_1, map_adj' := map_adj'_1 } → toEquiv = toEquiv_1

∀ {E_dom : Type u_7} {inst : NormedAddCommGroup E_dom} {inst_1 : NormedSpace ℝ E_dom} {H_dom : Type u_8}
  {inst_2 : TopologicalSpace H_dom} {I_dom : ModelWithCorners ℝ E_dom H_dom} {«Σ» : Type u_9}
  {inst_3 : TopologicalSpace «Σ»} {inst_4 : ChartedSpace H_dom «Σ»} {inst_5 : IsManifold I_dom (↑⊤) «Σ»}
  [self : GromovCompactness.RiemannDomain E_dom H_dom I_dom «Σ»] (z : «Σ») (v : TangentSpace I_dom z),
  (GromovCompactness.RiemannDomain.j z) ((GromovCompactness.RiemannDomain.j z) v) = -v

∀ {E : Type u_1} {inst : NormedAddCommGroup E} {inst_1 : NormedSpace ℝ E} {H : Type u_2} {inst_2 : TopologicalSpace H}
  {I : ModelWithCorners ℝ E H} {M : Type u_7} {inst_3 : TopologicalSpace M} {inst_4 : ChartedSpace H M}
  {inst_5 : IsManifold I (↑⊤) M} {inst_6 : CompactSpace M} {inst_7 : GromovCompactness.ClosedTameTarget I M} {r_inj : ℝ}
  {r_inj_pos : 0 < r_inj} {r_conv : ℝ} {r_conv_pos : 0 < r_conv} {chart_bound : ℝ} {chart_bound_pos : 0 < chart_bound}
  {r_inj_1 : ℝ} {r_inj_pos_1 : 0 < r_inj_1} {r_conv_1 : ℝ} {r_conv_pos_1 : 0 < r_conv_1} {chart_bound_1 : ℝ}
  {chart_bound_pos_1 : 0 < chart_bound_1},
  { r_inj := r_inj, r_inj_pos := r_inj_pos, r_conv := r_conv, r_conv_pos := r_conv_pos, chart_bound := chart_bound,
        chart_bound_pos := chart_bound_pos } =
      { r_inj := r_inj_1, r_inj_pos := r_inj_pos_1, r_conv := r_conv_1, r_conv_pos := r_conv_pos_1,
        chart_bound := chart_bound_1, chart_bound_pos := chart_bound_pos_1 } →
    r_inj = r_inj_1 ∧ r_conv = r_conv_1 ∧ chart_bound = chart_bound_1

∀ {E : Type u_1} {inst : NormedAddCommGroup E} {inst_1 : NormedSpace ℝ E} {H : Type u_2} {inst_2 : TopologicalSpace H}
  {I : ModelWithCorners ℝ E H} {M : Type u_3} {inst_3 : MetricSpace M} {inst_4 : ChartedSpace H M}
  {inst_5 : IsManifold I (↑⊤) M} {inst_6 : CompactSpace M} {inst_7 : GromovCompactness.ClosedTameTarget I M}
  {u_seq : ℕ → ↑GromovCompactness.CP1 → M} {tree : GromovCompactness.SphereTree} {root : tree.V}
  {map : tree.V → ↑GromovCompactness.CP1 → M}
  {is_jhol : ∀ (v : tree.V), GromovCompactness.JHolomorphicOn I GromovCompactness.I_CP1 (map v) Set.univ}
  {nodal_match : ∀ (v w : tree.V) (h : tree.adj.Adj v w), map v (tree.node_point v w h) = map w (tree.node_point w v ⋯)}
  {stable_off_root :
    ∀ (v : tree.V), v ≠ root → (∃ c, ∀ (z : ↑GromovCompactness.CP1), map v z = c) → 3 ≤ tree.adj.degree v}
  {σ : GromovCompactness.Bookkeeping.SubseqMap} {frames : tree.V → ℕ → GromovCompactness.MoebiusFrame}
  {root_frame_id : ∀ (n : ℕ), frames root n = GromovCompactness.MoebiusFrame.id}
  {frame_collapse :
    ∀ (v w : tree.V) (h : tree.adj.Adj v w),
      ∀ K ⊆ GromovCompactness.punctured_sphere {tree.node_point w v ⋯},
        IsCompact K →
          TendstoUniformlyOn (fun n => ⇑((frames v n).inv.comp (frames w n)).toHomeo) (fun x => tree.node_point v w h)
            Filter.atTop K}
  {smooth_conv :
    ∀ (v : tree.V),
      GromovCompactness.SmoothLocalConvergesOn I (fun n => u_seq (↑σ n) ∘ ⇑(frames v n).toHomeo) (map v)
        (GromovCompactness.punctured_sphere {z | ∃ w, ∃ (h : tree.adj.Adj v w), z = tree.node_point v w h})}
  {energy_ident :
    Filter.Tendsto (fun n => GromovCompactness.totalEnergy I (u_seq (↑σ n))) Filter.atTop
      (nhds (∑ v : tree.V, GromovCompactness.totalEnergy I (map v)))}
  {tree_1 : GromovCompactness.SphereTree} {root_1 : tree_1.V} {map_1 : tree_1.V → ↑GromovCompactness.CP1 → M}
  {is_jhol_1 : ∀ (v : tree_1.V), GromovCompactness.JHolomorphicOn I GromovCompactness.I_CP1 (map_1 v) Set.univ}
  {nodal_match_1 :
    ∀ (v w : tree_1.V) (h : tree_1.adj.Adj v w), map_1 v (tree_1.node_point v w h) = map_1 w (tree_1.node_point w v ⋯)}
  {stable_off_root_1 :
    ∀ (v : tree_1.V), v ≠ root_1 → (∃ c, ∀ (z : ↑GromovCompactness.CP1), map_1 v z = c) → 3 ≤ tree_1.adj.degree v}
  {σ_1 : GromovCompactness.Bookkeeping.SubseqMap} {frames_1 : tree_1.V → ℕ → GromovCompactness.MoebiusFrame}
  {root_frame_id_1 : ∀ (n : ℕ), frames_1 root_1 n = GromovCompactness.MoebiusFrame.id}
  {frame_collapse_1 :
    ∀ (v w : tree_1.V) (h : tree_1.adj.Adj v w),
      ∀ K ⊆ GromovCompactness.punctured_sphere {tree_1.node_point w v ⋯},
        IsCompact K →
          TendstoUniformlyOn (fun n => ⇑((frames_1 v n).inv.comp (frames_1 w n)).toHomeo)
            (fun x => tree_1.node_point v w h) Filter.atTop K}
  {smooth_conv_1 :
    ∀ (v : tree_1.V),
      GromovCompactness.SmoothLocalConvergesOn I (fun n => u_seq (↑σ_1 n) ∘ ⇑(frames_1 v n).toHomeo) (map_1 v)
        (GromovCompactness.punctured_sphere {z | ∃ w, ∃ (h : tree_1.adj.Adj v w), z = tree_1.node_point v w h})}
  {energy_ident_1 :
    Filter.Tendsto (fun n => GromovCompactness.totalEnergy I (u_seq (↑σ_1 n))) Filter.atTop
      (nhds (∑ v : tree_1.V, GromovCompactness.totalEnergy I (map_1 v)))},
  { tree := tree, root := root, map := map, is_jhol := is_jhol, nodal_match := nodal_match,
        stable_off_root := stable_off_root, σ := σ, frames := frames, root_frame_id := root_frame_id,
        frame_collapse := frame_collapse, smooth_conv := smooth_conv, energy_ident := energy_ident } =
      { tree := tree_1, root := root_1, map := map_1, is_jhol := is_jhol_1, nodal_match := nodal_match_1,
        stable_off_root := stable_off_root_1, σ := σ_1, frames := frames_1, root_frame_id := root_frame_id_1,
        frame_collapse := frame_collapse_1, smooth_conv := smooth_conv_1, energy_ident := energy_ident_1 } →
    tree = tree_1 ∧ HEq root root_1 ∧ HEq map map_1 ∧ σ = σ_1 ∧ HEq frames frames_1

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {H : Type u_2} [inst_2 : TopologicalSpace H]
  {I : ModelWithCorners ℝ E H} {M : Type u_3} [inst_3 : MetricSpace M] [inst_4 : ChartedSpace H M]
  [inst_5 : IsManifold I (↑⊤) M] [inst_6 : CompactSpace M] [inst_7 : GromovCompactness.ClosedTameTarget I M] {k : ℕ}
  {u_seq : ℕ → GromovCompactness.Extensions.MarkedSphere M k}
  {u_lim : GromovCompactness.Extensions.MarkedStableTreeLimit I k}
  (self : GromovCompactness.Extensions.MarkedCompactnessWitness I u_seq u_lim) (v : u_lim.tree.V),
  GromovCompactness.SmoothLocalConvergesOn I (fun n => (u_seq (↑self.σ n)).map ∘ ⇑(self.frames v n).toHomeo)
    (u_lim.map v)
    (GromovCompactness.punctured_sphere {z | ∃ w, ∃ (h : u_lim.tree.adj.Adj v w), z = u_lim.tree.node_point v w h})

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {H : Type u_2} [inst_2 : TopologicalSpace H]
  (I : ModelWithCorners ℝ E H) {M : Type u_3} [inst_3 : TopologicalSpace M] [inst_4 : ChartedSpace H M] {«Σ» : Type u_4}
  (u : «Σ» → M) (z : «Σ»), ContinuousConstSMul ℝ (TangentSpace I (u z))

doc:
Three-point transitivity theorem for the Möbius group PGL(2, ℂ):
for any three pairwise distinct projective points v₁, v₂, v₃ and any three pairwise distinct projective points w₁, w₂, w₃,
there exists a Möbius matrix M mapping v_i to w_i for i = 1, 2, 3.

type:
∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {H : Type u_2} [inst_2 : TopologicalSpace H]
  {I : ModelWithCorners ℝ E H} {M : Type u_3} [inst_3 : MetricSpace M] [inst_4 : ChartedSpace H M]
  [inst_5 : IsManifold I (↑⊤) M] [inst_6 : CompactSpace M] [inst_7 : GromovCompactness.ClosedTameTarget I M] {k : ℕ}
  (self : GromovCompactness.Extensions.MarkedStableTreeLimit I k) (v : self.tree.V),
  (∃ c, ∀ (z : ↑GromovCompactness.CP1), self.map v z = c) →
    3 ≤ self.tree.adj.degree v + Fintype.card { i // self.mark_vertex i = v }

∀ {E : Type u_1} {inst : NormedAddCommGroup E} {inst_1 : NormedSpace ℝ E} {H : Type u_2} {inst_2 : TopologicalSpace H}
  {I : ModelWithCorners ℝ E H} {M : Type u_3} {inst_3 : MetricSpace M} {inst_4 : ChartedSpace H M}
  {inst_5 : IsManifold I (↑⊤) M} {inst_6 : CompactSpace M} {inst_7 : GromovCompactness.ClosedTameTarget I M} {k : ℕ}
  {tree : GromovCompactness.Extensions.MarkedSphereTree k} {map : tree.V → ↑GromovCompactness.CP1 → M}
  {is_jhol : ∀ (v : tree.V), GromovCompactness.JHolomorphicOn I GromovCompactness.I_CP1 (map v) Set.univ}
  {nodal_match : ∀ (v w : tree.V) (h : tree.adj.Adj v w), map v (tree.node_point v w h) = map w (tree.node_point w v ⋯)}
  {stable :
    ∀ (v : tree.V),
      (∃ c, ∀ (z : ↑GromovCompactness.CP1), map v z = c) → 3 ≤ GromovCompactness.Extensions.special_degree tree v}
  {tree_1 : GromovCompactness.Extensions.MarkedSphereTree k} {map_1 : tree_1.V → ↑GromovCompactness.CP1 → M}
  {is_jhol_1 : ∀ (v : tree_1.V), GromovCompactness.JHolomorphicOn I GromovCompactness.I_CP1 (map_1 v) Set.univ}
  {nodal_match_1 :
    ∀ (v w : tree_1.V) (h : tree_1.adj.Adj v w), map_1 v (tree_1.node_point v w h) = map_1 w (tree_1.node_point w v ⋯)}
  {stable_1 :
    ∀ (v : tree_1.V),
      (∃ c, ∀ (z : ↑GromovCompactness.CP1), map_1 v z = c) → 3 ≤ GromovCompactness.Extensions.special_degree tree_1 v},
  { tree := tree, map := map, is_jhol := is_jhol, nodal_match := nodal_match, stable := stable } =
      { tree := tree_1, map := map_1, is_jhol := is_jhol_1, nodal_match := nodal_match_1, stable := stable_1 } →
    tree = tree_1 ∧ HEq map map_1

∀ {k : ℕ} {toSphereTree : GromovCompactness.SphereTree} {mark_vertex : Fin k → toSphereTree.V}
  {mark_point : Fin k → ↑GromovCompactness.CP1}
  {mark_distinct : ∀ (i j : Fin k), i ≠ j → mark_vertex i = mark_vertex j → mark_point i ≠ mark_point j}
  {mark_node_distinct :
    ∀ (i : Fin k) (w : toSphereTree.V) (h : toSphereTree.adj.Adj (mark_vertex i) w),
      mark_point i ≠ toSphereTree.node_point (mark_vertex i) w h}
  {toSphereTree_1 : GromovCompactness.SphereTree} {mark_vertex_1 : Fin k → toSphereTree_1.V}
  {mark_point_1 : Fin k → ↑GromovCompactness.CP1}
  {mark_distinct_1 : ∀ (i j : Fin k), i ≠ j → mark_vertex_1 i = mark_vertex_1 j → mark_point_1 i ≠ mark_point_1 j}
  {mark_node_distinct_1 :
    ∀ (i : Fin k) (w : toSphereTree_1.V) (h : toSphereTree_1.adj.Adj (mark_vertex_1 i) w),
      mark_point_1 i ≠ toSphereTree_1.node_point (mark_vertex_1 i) w h},
  { toSphereTree := toSphereTree, mark_vertex := mark_vertex, mark_point := mark_point, mark_distinct := mark_distinct,
        mark_node_distinct := mark_node_distinct } =
      { toSphereTree := toSphereTree_1, mark_vertex := mark_vertex_1, mark_point := mark_point_1,
        mark_distinct := mark_distinct_1, mark_node_distinct := mark_node_distinct_1 } →
    toSphereTree = toSphereTree_1 ∧ HEq mark_vertex mark_vertex_1 ∧ mark_point = mark_point_1

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {H : Type u_2} [inst_2 : TopologicalSpace H]
  (I : ModelWithCorners ℝ E H) {M : Type u_3} [inst_3 : TopologicalSpace M] [inst_4 : ChartedSpace H M] {«Σ» : Type u_4}
  (u : «Σ» → M) (z : «Σ»), ContinuousAdd (TangentSpace I (u z))

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {H : Type u_2} [inst_2 : TopologicalSpace H]
  (I : ModelWithCorners ℝ E H) {M : Type u_3} [inst_3 : MetricSpace M] [inst_4 : ChartedSpace H M]
  [inst_5 : IsManifold I (↑⊤) M] [inst_6 : CompactSpace M] [inst_7 : GromovCompactness.ClosedTameTarget I M] {k : ℕ}
  (th : GromovCompactness.Bubbling.TargetThresholds I M)
  (u_lim : GromovCompactness.Extensions.MarkedStableTreeLimit I k) (B : ℝ),
  GromovCompactness.Extensions.markedTreeTotalEnergy I u_lim ≤ B →
    let P := Fintype.card { v // GromovCompactness.Extensions.is_principal_component_marked I u_lim v };
    let G := Fintype.card { v // GromovCompactness.Extensions.is_ghost_component_marked I u_lim v };
    ↑P * th.h ≤ B ∧
      (1 < Fintype.card u_lim.tree.V → G ≤ P + k - 2) ∧ ↑(Fintype.card u_lim.tree.V) ≤ 1 ⊔ (2 * ⌊B / th.h⌋ + ↑k - 2)

∀ {E : Type u_1} {inst : NormedAddCommGroup E} {inst_1 : NormedSpace ℝ E} {H : Type u_2} {inst_2 : TopologicalSpace H}
  {I : ModelWithCorners ℝ E H} {M : Type u_3} {inst_3 : MetricSpace M} {inst_4 : ChartedSpace H M}
  {inst_5 : IsManifold I (↑⊤) M} {inst_6 : CompactSpace M} {inst_7 : GromovCompactness.ClosedTameTarget I M} {k : ℕ}
  {u_seq : ℕ → GromovCompactness.Extensions.MarkedSphere M k}
  {u_lim : GromovCompactness.Extensions.MarkedStableTreeLimit I k} {σ : GromovCompactness.Bookkeeping.SubseqMap}
  {frames : u_lim.tree.V → ℕ → GromovCompactness.MoebiusFrame}
  {smooth_conv :
    ∀ (v : u_lim.tree.V),
      GromovCompactness.SmoothLocalConvergesOn I (fun n => (u_seq (↑σ n)).map ∘ ⇑(frames v n).toHomeo) (u_lim.map v)
        (GromovCompactness.punctured_sphere {z | ∃ w, ∃ (h : u_lim.tree.adj.Adj v w), z = u_lim.tree.node_point v w h})}
  {frame_collapse :
    ∀ (v w : u_lim.tree.V) (h : u_lim.tree.adj.Adj v w),
      ∀ K ⊆ GromovCompactness.punctured_sphere {u_lim.tree.node_point w v ⋯},
        IsCompact K →
          TendstoUniformlyOn (fun n => ⇑((frames v n).inv.comp (frames w n)).toHomeo)
            (fun x => u_lim.tree.node_point v w h) Filter.atTop K}
  {mark_conv :
    ∀ (i : Fin k),
      Filter.Tendsto (fun n => (frames (u_lim.mark_vertex i) n).inv.toHomeo ((u_seq (↑σ n)).points i)) Filter.atTop
        (nhds (u_lim.mark_point i))}
  {energy_conv :
    Filter.Tendsto (fun n => GromovCompactness.totalEnergy I (u_seq (↑σ n)).map) Filter.atTop
      (nhds (GromovCompactness.Extensions.markedTreeTotalEnergy I u_lim))}
  {σ_1 : GromovCompactness.Bookkeeping.SubseqMap} {frames_1 : u_lim.tree.V → ℕ → GromovCompactness.MoebiusFrame}
  {smooth_conv_1 :
    ∀ (v : u_lim.tree.V),
      GromovCompactness.SmoothLocalConvergesOn I (fun n => (u_seq (↑σ_1 n)).map ∘ ⇑(frames_1 v n).toHomeo) (u_lim.map v)
        (GromovCompactness.punctured_sphere {z | ∃ w, ∃ (h : u_lim.tree.adj.Adj v w), z = u_lim.tree.node_point v w h})}
  {frame_collapse_1 :
    ∀ (v w : u_lim.tree.V) (h : u_lim.tree.adj.Adj v w),
      ∀ K ⊆ GromovCompactness.punctured_sphere {u_lim.tree.node_point w v ⋯},
        IsCompact K →
          TendstoUniformlyOn (fun n => ⇑((frames_1 v n).inv.comp (frames_1 w n)).toHomeo)
            (fun x => u_lim.tree.node_point v w h) Filter.atTop K}
  {mark_conv_1 :
    ∀ (i : Fin k),
      Filter.Tendsto (fun n => (frames_1 (u_lim.mark_vertex i) n).inv.toHomeo ((u_seq (↑σ_1 n)).points i)) Filter.atTop
        (nhds (u_lim.mark_point i))}
  {energy_conv_1 :
    Filter.Tendsto (fun n => GromovCompactness.totalEnergy I (u_seq (↑σ_1 n)).map) Filter.atTop
      (nhds (GromovCompactness.Extensions.markedTreeTotalEnergy I u_lim))},
  { σ := σ, frames := frames, smooth_conv := smooth_conv, frame_collapse := frame_collapse, mark_conv := mark_conv,
        energy_conv := energy_conv } =
      { σ := σ_1, frames := frames_1, smooth_conv := smooth_conv_1, frame_collapse := frame_collapse_1,
        mark_conv := mark_conv_1, energy_conv := energy_conv_1 } →
    σ = σ_1 ∧ frames = frames_1

∀ {E : Type u_1} {inst : NormedAddCommGroup E} {inst_1 : NormedSpace ℝ E} {H : Type u_2} {inst_2 : TopologicalSpace H}
  {I : ModelWithCorners ℝ E H} {M : Type u_4} {inst_3 : TopologicalSpace M} {inst_4 : ChartedSpace H M}
  {inst_5 : IsManifold I (↑⊤) M} {inst_6 : CompactSpace M} [self : GromovCompactness.ClosedTameTarget I M] (x : M)
  (v : TangentSpace I x), (∀ (w : TangentSpace I x), ((GromovCompactness.ClosedTameTarget.ω x) v) w = 0) → v = 0

∀ {E : Type u_1} {inst : NormedAddCommGroup E} {inst_1 : NormedSpace ℝ E} {H : Type u_2} {inst_2 : TopologicalSpace H}
  {I : ModelWithCorners ℝ E H} {M : Type u_4} {inst_3 : TopologicalSpace M} {inst_4 : ChartedSpace H M}
  {inst_5 : IsManifold I (↑⊤) M} {inst_6 : CompactSpace M} [self : GromovCompactness.ClosedTameTarget I M] (x : M)
  (v : TangentSpace I x),
  v ≠ 0 → 0 < ((GromovCompactness.ClosedTameTarget.ω x) v) ((GromovCompactness.ClosedTameTarget.J x) v)

∀ {seq : ℕ → GromovCompactness.MoebiusFrame} {lim : GromovCompactness.MoebiusFrame}
  {tendsto : Filter.Tendsto seq Filter.atTop (nhds lim)} {seq_1 : ℕ → GromovCompactness.MoebiusFrame}
  {lim_1 : GromovCompactness.MoebiusFrame} {tendsto_1 : Filter.Tendsto seq_1 Filter.atTop (nhds lim_1)},
  { seq := seq, lim := lim, tendsto := tendsto } = { seq := seq_1, lim := lim_1, tendsto := tendsto_1 } →
    seq = seq_1 ∧ lim = lim_1

∀ {E : Type u_1} {inst : NormedAddCommGroup E} {inst_1 : NormedSpace ℝ E} {H : Type u_2} {inst_2 : TopologicalSpace H}
  {I : ModelWithCorners ℝ E H} {M : Type u_4} {inst_3 : MetricSpace M} {inst_4 : ChartedSpace H M}
  {inst_5 : IsManifold I (↑⊤) M} {inst_6 : CompactSpace M} {inst_7 : GromovCompactness.ClosedTameTarget I M} {H₂ : Type}
  {addCommGroup : AddCommGroup H₂} {cycleClass : (↑GromovCompactness.CP1 → M) → H₂}
  {homotopy_invariant :
    ∀ (u₁ u₂ : ↑GromovCompactness.CP1 → M),
      GromovCompactness.Extensions.ContinuousHomotopic u₁ u₂ → cycleClass u₁ = cycleClass u₂}
  {omegaPairing : H₂ →+ ℝ}
  {omegaPairing_eq_area :
    ∀ (u : ↑GromovCompactness.CP1 → M),
      omegaPairing (cycleClass u) = GromovCompactness.pullbackOmegaMeasure I u Set.univ}
  {cycleClass_neck_degeneration :
    ∀ (u_seq : ℕ → ↑GromovCompactness.CP1 → M) (u_lim : GromovCompactness.StableSphereTreeLimit I)
      (wit : GromovCompactness.CompactnessWitness I u_seq u_lim),
      (∀ (n : ℕ), GromovCompactness.JHolomorphicOn I GromovCompactness.I_CP1 (u_seq n) Set.univ) →
        ∀ᶠ (n : ℕ) in Filter.atTop, cycleClass (u_seq (↑wit.σ n)) = ∑ v : u_lim.tree.V, cycleClass (u_lim.map v)}
  {H₂_1 : Type} {addCommGroup_1 : AddCommGroup H₂_1} {cycleClass_1 : (↑GromovCompactness.CP1 → M) → H₂_1}
  {homotopy_invariant_1 :
    ∀ (u₁ u₂ : ↑GromovCompactness.CP1 → M),
