                    r₂ < R →
                      GromovCompactness.energyMeasure I u (GromovCompactness.annulus_at center r₁ r₂) ≤
                        C_neck * ((r / r₁) ^ a_decay + (r₂ / R) ^ a_decay) *
                          GromovCompactness.energyMeasure I u (GromovCompactness.annulus_at center r R)}
  {h : ℝ} {h_pos : 0 < h} {h_le_reg : h ≤ ε_reg / 2} {h_le_sph : h ≤ ε_sph} {h_le_neck : h ≤ ε_neck / 2} {ε_reg_1 : ℝ}
